  // Верните [значение global, значение function, значение block].
}

01-javascript/07-scope.solution:
const level = 'global';

function describeScope() {
  const outer = level;
  const level2 = 'function';
  let blockValue;

  {
    const level = 'block';
    blockValue = level;
  }

  return [outer, level2, blockValue];
}

01-javascript/07-scope.starter:
function createStore() {
  // Верните объект с методами add, all и size.
}

tests.code:
const store = createStore();
store.add('a');
store.add('b');
expect(store.all()).toEqual(['a', 'b']);
expect(store.size()).toBe(2);

const store = createStore();
store.add('a');
const items = store.all();
items.push('подделка');
expect(store.size()).toBe(1);

const first = createStore();
const second = createStore();
first.add('a');
expect(second.size()).toBe(0);

01-javascript/07-scope.solution:
function createStore() {
  const items = [];

  return {
    add(item) {
      items.push(item);
    },
    all() {
      return [...items];
    },
    size() {
      return items.length;
    }
  };
}
